"use client";
import { useEffect, useRef, useState } from "react";

/**
 * Nataraja rendered as a lit, displaced 3D relief (WebGL2), revealed out of gold dust.
 *
 * Assets (generated by scripts/build_depth.py from the cut-out):
 *  - nataraja.webp          colour + alpha
 *  - nataraja-depth.png     R = depth hi byte, B = depth lo byte (16-bit), G = ambient occlusion
 *  - nataraja-normal.webp   object-space normals (body volume + engraving micro-detail)
 *
 * Reveal: a soft, grainy front (a noise field computed once on the CPU and shared with
 * the shader, so particles spawn exactly on the visible edge) rises through the statue.
 * As it passes, fine gold dust lifts off the surface and settles. Scrolling away runs it
 * backwards: the statue crumbles top-down into sand that pours with gravity, and gathers
 * back when you return. Grains are lit as tiny spheres; larger chips carry a patch of the
 * carving they broke from and tumble, flashing as they catch the light.
 *
 * Shading: baked AO, cursor-driven key light, Fresnel rim and a studio environment
 * reflected off the gold. Motion: pointer tilt, drag-to-turn with inertia, hover dolly,
 * scroll-linked camera. Every motion is a damped spring.
 */

const VERT = `#version 300 es
in vec2 aPos;
uniform sampler2D uDepth;
uniform mat4 uProj, uModel;
uniform float uDepthScale, uAspect, uFlat, uZOff;
out vec2 vUv;
out vec3 vWorld;
float depthAt(vec2 uv) { vec4 d = texture(uDepth, uv); return (d.r * 65280.0 + d.b * 255.0) / 65535.0; }
void main() {
  vUv = vec2(aPos.x + 0.5, 0.5 - aPos.y);
  float d = uFlat > 0.5 ? 0.0 : depthAt(vUv);
  vec3 p = vec3(aPos.x * uAspect, aPos.y, d * uDepthScale + uZOff);
  vec4 w = uModel * vec4(p, 1.0);
  vWorld = w.xyz;
  gl_Position = uProj * w;
}`;

const FRAG = `#version 300 es
precision highp float;
uniform sampler2D uColor, uDepth, uNormal, uFront;
uniform mat3 uRot;
uniform vec3 uLight;
uniform float uFrontP, uFlat, uShadowAlpha, uAspect;
in vec2 vUv;
in vec3 vWorld;
out vec4 o;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p); vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), u.x), mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), u.x), u.y);
}

vec3 env(vec3 r) {
  float h = r.y;
  vec3 c = mix(vec3(0.10, 0.03, 0.04), vec3(0.55, 0.36, 0.16), smoothstep(-0.6, 0.25, h));
  c = mix(c, vec3(0.95, 0.80, 0.55), smoothstep(0.35, 0.9, h) * 0.6);
  c += vec3(1.0, 0.88, 0.62) * smoothstep(0.82, 0.98, dot(r, normalize(vec3(-0.55, 0.45, 0.7)))) * 1.2;
  c += vec3(0.9, 0.55, 0.35) * smoothstep(0.86, 0.99, dot(r, normalize(vec3(0.7, 0.1, 0.6)))) * 0.6;
  return c;
}

void main() {
  // reveal front: shared field + a fine grain so the edge breaks like powder, not a wipe
  float g = vnoise(vUv * vec2(260.0 * uAspect, 260.0)) * 0.6 + vnoise(vUv * vec2(70.0 * uAspect, 70.0)) * 0.4;
  float T = texture(uFront, vUv).r + (g - 0.5) * 0.035;
  float e = uFrontP - T;                       // > 0 means formed
  if (uFlat > 0.5) {                           // soft cast shadow on the backdrop
    float a = textureLod(uColor, vUv, 5.5).a * smoothstep(-0.05, 0.25, uFrontP - texture(uFront, vUv).r);
    o = vec4(0.06, 0.0, 0.02, a * uShadowAlpha);
    return;
  }
  vec4 c = texture(uColor, vUv);
  float a = smoothstep(0.42, 0.62, c.a);
  float keep = smoothstep(0.0, 0.012, e);
  a *= keep;
  if (a < 0.02) discard;

  vec4 dz = texture(uDepth, vUv);
  float ao = mix(0.35, 1.0, dz.g);
  // the photo already carries the true shading; normals only add a gentle response to the light
  vec3 n = normalize(uRot * normalize(mix(vec3(0.0, 0.0, 1.0), texture(uNormal, vUv).rgb * 2.0 - 1.0, 0.5)));
  vec3 V = normalize(-vWorld);
  vec3 L = normalize(uLight);
  vec3 H = normalize(L + V);
  float ndl = max(dot(n, L), 0.0);
  float ndh = max(dot(n, H), 0.0);
  float ndv = max(dot(n, V), 0.0);
  float fres = pow(1.0 - ndv, 3.0);
  float lum = dot(c.rgb, vec3(0.299, 0.587, 0.114));

  vec3 gold = c.rgb;
  vec3 R = reflect(-V, n);
  vec3 col = gold * mix(0.9, 1.1, ndl) * mix(0.8, 1.0, ao);
  col += gold * env(R) * 0.16 * (0.3 + fres);
  col += vec3(1.0, 0.9, 0.7) * pow(ndh, 160.0) * 0.4 * smoothstep(0.35, 0.85, lum);
  col += gold * pow(ndh, 14.0) * 0.05;
  col += vec3(0.9, 0.5, 0.28) * fres * 0.04 * ao;
  col = pow(col, vec3(1.03));

  // freshly formed metal: a narrow warm band that cools as the front moves on
  float band = 1.0 - smoothstep(0.0, 0.06, e);
  float lip = 1.0 - smoothstep(0.0, 0.018, e);
  col = mix(col, col * 0.55, lip * 0.5);                         // shadowed powder lip
  col += vec3(1.0, 0.74, 0.4) * band * (0.35 + 0.65 * g) * 0.55 * (0.4 + lum);
  o = vec4(col, a);
}`;

/* Dust & sand. Kind 0 = fine grain (lit sphere), 1 = chip (tumbling facet carrying a patch
   of the carving), 2 = soft powder puff. */
const PVERT = `#version 300 es
in vec3 aPos;
in vec2 aUv;
in vec4 aMisc;   // alpha, size, rot, kind
in vec2 aMisc2;  // hot, seed
uniform mat4 uProj, uModel;
uniform float uPx;
out vec2 vUv;
out float vAlpha, vRot, vKind, vHot, vSeed, vSpan;
void main() {
  vUv = aUv; vAlpha = aMisc.x; vRot = aMisc.z; vKind = aMisc.w; vHot = aMisc2.x; vSeed = aMisc2.y;
  vSpan = aMisc.y * 0.0021;
  vec4 mv = uModel * vec4(aPos, 1.0);
  gl_Position = uProj * mv;
  gl_PointSize = aMisc.y * uPx * (2.0 / -mv.z);
}`;

const PFRAG = `#version 300 es
precision highp float;
uniform sampler2D uColor;
uniform vec3 uLight;
uniform float uAspect;
in vec2 vUv;
in float vAlpha, vRot, vKind, vHot, vSeed, vSpan;
out vec4 o;
void main() {
  if (vAlpha < 0.01) discard;
  vec2 p = gl_PointCoord - 0.5; p.y = -p.y;
  if (vKind > 1.5) {                         // powder puff
    float r = length(p);
    float a = smoothstep(0.5, 0.0, r);
    o = vec4(vec3(0.86, 0.64, 0.36), a * a * vAlpha);
    return;
  }
  float c = cos(vRot), s = sin(vRot);
  vec2 q = vec2(c * p.x - s * p.y, s * p.x + c * p.y);
  float r = length(q);
  float ang = atan(q.y, q.x) + 3.14159;
  float facet = 0.5 * (0.66 + 0.34 * fract(sin(floor(ang * 1.12) * 91.7 + vSeed * 13.0) * 43758.5453));
  float outline = mix(0.5, facet, vKind);
  if (r > outline) discard;

  vec3 L = normalize(uLight);
  vec3 sphere = normalize(vec3(q * 2.0, sqrt(max(0.0, 0.25 - r * r)) * 2.0 + 0.05));
  vec3 face = normalize(vec3(sin(vRot * 1.31 + vSeed) * 0.75, cos(vRot * 0.87 + vSeed) * 0.75, 0.55));
  vec3 n = normalize(mix(sphere, face, vKind));
  float diff = max(dot(n, L), 0.0);
  float spec = pow(max(dot(n, normalize(L + vec3(0.0, 0.0, 1.0))), 0.0), 28.0);

  vec3 alb = texture(uColor, vUv + q * vec2(vSpan / uAspect, vSpan) * vKind).rgb;
  vec3 col = alb * (0.35 + 1.05 * diff);
  col += vec3(1.0, 0.9, 0.68) * spec * (0.35 + 0.5 * vKind);
  col = mix(col, vec3(1.0, 0.8, 0.48) * 1.25, vHot);
  float aa = mix(smoothstep(0.5, 0.34, r), smoothstep(outline, outline - 0.05, r), vKind);
  o = vec4(col, vAlpha * aa);
}`;

type M4 = Float32Array;
const perspective = (fov: number, aspect: number, near: number, far: number): M4 => {
  const f = 1 / Math.tan(fov / 2), nf = 1 / (near - far);
  return new Float32Array([f / aspect, 0, 0, 0, 0, f, 0, 0, 0, 0, (far + near) * nf, -1, 0, 0, 2 * far * near * nf, 0]);
};
// Rotation R = Rx(rx) * Ry(ry), column-major 3x3
const rot = (rx: number, ry: number) => {
  const cx = Math.cos(rx), sx = Math.sin(rx), cy = Math.cos(ry), sy = Math.sin(ry);
  return [cy, sx * sy, -cx * sy, 0, cx, sx, sy, -sx * cy, cx * cy];
};
const mat4 = (r: number[], tx: number, ty: number, tz: number): M4 =>
  new Float32Array([r[0], r[1], r[2], 0, r[3], r[4], r[5], 0, r[6], r[7], r[8], 0, tx, ty, tz, 1]);

const load = (src: string) => new Promise<HTMLImageElement>((res, rej) => {
  const i = new Image(); i.decoding = "async"; i.onload = () => res(i); i.onerror = rej; i.src = src;
});
const easeInOut = (x: number) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);
const clamp01 = (x: number) => Math.min(1, Math.max(0, x));
const smooth = (a: number, b: number, x: number) => { const t = clamp01((x - a) / (b - a)); return t * t * (3 - 2 * t); };

/* Reveal field: mostly bottom-to-top, broken up by two octaves of smooth noise. */
function buildFront(W: number, H: number) {
  const rnd = (x: number, y: number) => { const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return s - Math.floor(s); };
  const vn = (x: number, y: number) => {
    const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy;
    const ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy);
    const a = rnd(ix, iy), b = rnd(ix + 1, iy), c = rnd(ix, iy + 1), d = rnd(ix + 1, iy + 1);
    return (a + (b - a) * ux) + ((c + (d - c) * ux) - (a + (b - a) * ux)) * uy;
  };
  const f = new Float32Array(W * H);
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    const u = x / (W - 1), v = y / (H - 1);
    const n = vn(u * 7, v * 9) * 0.65 + vn(u * 24 + 3.1, v * 31 + 7.7) * 0.35;
    f[y * W + x] = clamp01((1 - v) * 0.84 + n * 0.16);
  }
  return f;
}

export default function Statue3D({
  src, depthSrc, normalSrc, alt, hostRef,
}: { src: string; depthSrc: string; normalSrc: string; alt: string; hostRef?: React.RefObject<HTMLElement | null> }) {
  const wrap = useRef<HTMLDivElement>(null);
  const canvas = useRef<HTMLCanvasElement>(null);
  const [ready, setReady] = useState(false);
  const [fallback, setFallback] = useState(false);

  useEffect(() => {
    const cv = canvas.current!, box = wrap.current!;
    const gl = cv.getContext("webgl2", { alpha: true, antialias: true, premultipliedAlpha: false });
    if (!gl) { setFallback(true); return; }
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const small = window.matchMedia("(max-width: 860px)").matches;
    const amp = reduce ? 0.3 : 1;
    let disposed = false, raf = 0, visible = true;

    const program = (vs: string, fs: string) => {
      const sh = (type: number, s: string) => {
        const o = gl.createShader(type)!; gl.shaderSource(o, s); gl.compileShader(o);
        if (!gl.getShaderParameter(o, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(o) || "shader");
        return o;
      };
      const p = gl.createProgram()!;
      gl.attachShader(p, sh(gl.VERTEX_SHADER, vs)); gl.attachShader(p, sh(gl.FRAGMENT_SHADER, fs));
      gl.linkProgram(p);
      if (!gl.getProgramParameter(p, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(p) || "link");
      return p;
    };
    let prog: WebGLProgram, pprog: WebGLProgram;
    try { prog = program(VERT, FRAG); pprog = program(PVERT, PFRAG); }
    catch (e) { console.warn(e); setFallback(true); return; }

    // ---- statue mesh ---------------------------------------------------
    const SX = small ? 180 : 260, SY = Math.round(SX * 1.4);
    const verts = new Float32Array((SX + 1) * (SY + 1) * 2);
    let k = 0;
    for (let y = 0; y <= SY; y++) for (let x = 0; x <= SX; x++) { verts[k++] = x / SX - 0.5; verts[k++] = 0.5 - y / SY; }
    const idx = new Uint32Array(SX * SY * 6); k = 0;
    for (let y = 0; y < SY; y++) for (let x = 0; x < SX; x++) {
      const i = y * (SX + 1) + x; idx.set([i, i + SX + 1, i + 1, i + 1, i + SX + 1, i + SX + 2], k); k += 6;
    }
    const meshVao = gl.createVertexArray(); gl.bindVertexArray(meshVao);
    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer()); gl.bufferData(gl.ARRAY_BUFFER, verts, gl.STATIC_DRAW);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, gl.createBuffer()); gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, idx, gl.STATIC_DRAW);
    const aPos = gl.getAttribLocation(prog, "aPos");
    gl.enableVertexAttribArray(aPos); gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

    const U = (p: WebGLProgram, n: string) => gl.getUniformLocation(p, n);
    const u = {
      proj: U(prog, "uProj"), model: U(prog, "uModel"), rot: U(prog, "uRot"), light: U(prog, "uLight"),
      depthScale: U(prog, "uDepthScale"), aspect: U(prog, "uAspect"), flat: U(prog, "uFlat"), zoff: U(prog, "uZOff"),
      front: U(prog, "uFrontP"), shadowA: U(prog, "uShadowAlpha"),
    };
    const pu = {
      proj: U(pprog, "uProj"), model: U(pprog, "uModel"), px: U(pprog, "uPx"), light: U(pprog, "uLight"), aspect: U(pprog, "uAspect"),
    };
    gl.useProgram(prog);
    gl.uniform1i(U(prog, "uColor"), 0); gl.uniform1i(U(prog, "uDepth"), 1);
    gl.uniform1i(U(prog, "uNormal"), 2); gl.uniform1i(U(prog, "uFront"), 3);
    gl.useProgram(pprog);
    gl.uniform1i(U(pprog, "uColor"), 0);

    const texture = (img: TexImageSource, unit: number, mip: boolean, linear = true) => {
      gl.activeTexture(gl.TEXTURE0 + unit);
      gl.bindTexture(gl.TEXTURE_2D, gl.createTexture());
      gl.pixelStorei(gl.UNPACK_COLORSPACE_CONVERSION_WEBGL, gl.NONE);
      gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
      const f = linear ? gl.LINEAR : gl.NEAREST;
      if (mip) { gl.generateMipmap(gl.TEXTURE_2D); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR); }
      else gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, f);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, f);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    };

    // ---- particles -----------------------------------------------------
    const MAX = reduce ? 0 : small ? 2600 : 6500;
    const STRIDE = 11; // pos3 uv2 alpha size rot kind hot seed
    const P = {
      pos: new Float32Array(MAX * 3), vel: new Float32Array(MAX * 3), uv: new Float32Array(MAX * 2),
      alpha: new Float32Array(MAX), size: new Float32Array(MAX), rot: new Float32Array(MAX), spin: new Float32Array(MAX),
      kind: new Float32Array(MAX), hot: new Float32Array(MAX), heat: new Float32Array(MAX), seed: new Float32Array(MAX),
      age: new Float32Array(MAX), life: new Float32Array(MAX).fill(-1), fall: new Float32Array(MAX),
    };
    const upload = new Float32Array(Math.max(1, MAX) * STRIDE);
    let head = 0, alive = 0;
    const pVao = gl.createVertexArray(); gl.bindVertexArray(pVao);
    const pBuf = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, pBuf);
    gl.bufferData(gl.ARRAY_BUFFER, upload.byteLength, gl.DYNAMIC_DRAW);
    const attr = (name: string, n: number, off: number) => {
      const l = gl.getAttribLocation(pprog, name); if (l < 0) return;
      gl.enableVertexAttribArray(l); gl.vertexAttribPointer(l, n, gl.FLOAT, false, STRIDE * 4, off * 4);
    };
    attr("aPos", 3, 0); attr("aUv", 2, 3); attr("aMisc", 4, 5); attr("aMisc2", 2, 9);
    gl.bindVertexArray(null);

    // CPU copies, sampled on a coarse grid to seed grains on the surface
    const GW = 210, GH = Math.round(GW * 1468 / 1048);
    let front: Float32Array | null = null;
    let cells: { u: Float32Array; v: Float32Array; d: Float32Array; t: Float32Array; n: number } | null = null;
    let imgAspect = 1048 / 1468, depthScale = 0.075;

    const spawn = (ux: number, uy: number, dz: number, mode: "form" | "fall", chip: boolean, puff: boolean) => {
      if (!MAX) return;
      const k = head; head = (head + 1) % MAX;
      const i = k * 3;
      P.pos[i] = (ux - 0.5) * imgAspect; P.pos[i + 1] = 0.5 - uy; P.pos[i + 2] = dz * depthScale + 0.004;
      P.uv[k * 2] = ux; P.uv[k * 2 + 1] = uy;
      P.seed[k] = Math.random(); P.age[k] = 0; P.rot[k] = Math.random() * 6.283;
      if (puff) {
        P.kind[k] = 2; P.size[k] = 16 + Math.random() * 20; P.life[k] = 1.6 + Math.random() * 1.4;
        P.vel[i] = (Math.random() - 0.5) * 0.04; P.vel[i + 1] = 0.01 + Math.random() * 0.035; P.vel[i + 2] = 0.02 + Math.random() * 0.04;
        P.spin[k] = 0; P.heat[k] = 0; P.fall[k] = 0;
        return;
      }
      P.kind[k] = chip ? 1 : 0;
      P.spin[k] = chip ? (Math.random() < 0.5 ? -1 : 1) * (2 + Math.random() * 6) : 0;
      if (mode === "form") {
        // dust lifting off freshly formed gold: buoyant, short-lived, some glinting
        P.size[k] = chip ? 3.4 + Math.random() * 3 : 1.1 + Math.pow(Math.random(), 2.5) * 2.2;
        P.vel[i] = (Math.random() - 0.5) * 0.05;
        P.vel[i + 1] = 0.03 + Math.random() * 0.09;
        P.vel[i + 2] = 0.03 + Math.random() * 0.1;
        P.life[k] = 0.9 + Math.random() * 1.3;
        P.heat[k] = Math.random() < 0.3 ? 0.6 + Math.random() * 0.4 : 0;
        P.fall[k] = 0;
      } else {
        // crumbling: the break pushes outward and toward the viewer, then gravity takes it
        const burst = chip ? 0.05 + Math.random() * 0.09 : 0.03 + Math.random() * 0.08;
        const ox = Math.random() - 0.5;
        P.size[k] = chip ? 4.2 + Math.random() * 4.6 : 1.3 + Math.pow(Math.random(), 2.5) * 2.4;
        P.vel[i] = ox * burst + (Math.random() - 0.5) * 0.06;
        P.vel[i + 1] = Math.random() * (chip ? 0.14 : 0.09);
        P.vel[i + 2] = 0.04 + Math.random() * (chip ? 0.18 : 0.1);
        P.life[k] = chip ? 2.4 : 1.8 + Math.random() * 1.6;
        P.heat[k] = !chip && Math.random() < 0.16 ? 0.7 + Math.random() * 0.3 : 0;
        P.fall[k] = 1;
      }
    };

    // spawn on cells the front crossed this frame (cells are sorted by their threshold)
    const lowerBound = (t: Float32Array, n: number, x: number) => { let a = 0, b = n; while (a < b) { const m = (a + b) >> 1; if (t[m] < x) a = m + 1; else b = m; } return a; };
    const emitBetween = (p0: number, p1: number, mode: "form" | "fall") => {
      if (!cells || !MAX || p0 === p1) return;
      const lo = Math.min(p0, p1), hi = Math.max(p0, p1);
      const a = lowerBound(cells.t, cells.n, lo), b = lowerBound(cells.t, cells.n, hi);
      const span = b - a; if (span <= 0) return;
      const budget = mode === "form" ? (small ? 28 : 64) : (small ? 50 : 120);
      const n = Math.min(span, budget);
      for (let j = 0; j < n; j++) {
        const c = a + Math.floor(Math.random() * span);
        const ux = cells.u[c] + (Math.random() - 0.5) / GW, uy = cells.v[c] + (Math.random() - 0.5) / GH;
        const chip = Math.random() < (mode === "form" ? 0.035 : 0.1);
        spawn(ux, uy, cells.d[c], mode, chip, false);
        if (Math.random() < (mode === "form" ? 0.02 : 0.04)) spawn(ux, uy, cells.d[c], mode, false, true);
      }
    };

    const simulate = (dt: number, t: number) => {
      let n = 0;
      for (let k = 0; k < MAX; k++) {
        if (P.life[k] < 0) continue;
        P.age[k] += dt;
        const i = k * 3;
        if (P.age[k] >= P.life[k] || P.pos[i + 1] < -0.72) { P.life[k] = -1; continue; }
        const kind = P.kind[k], life = P.age[k] / P.life[k];
        let alpha: number;
        if (kind > 1.5) {                                  // puff rises a little, swells, fades
          P.vel[i + 1] -= 0.012 * dt;
          P.size[k] += dt * 16;
          alpha = Math.sin(Math.PI * life) * 0.07;
        } else {
          const chip = kind > 0.5;
          if (P.fall[k] > 0) {
            P.vel[i + 1] -= (chip ? 1.9 : 1.25) * dt;
            const drag = Math.exp(-(chip ? 0.35 : 1.1) * dt);
            P.vel[i] *= drag; P.vel[i + 1] *= chip ? 1 : Math.exp(-0.35 * dt); P.vel[i + 2] *= drag;
          } else {
            P.vel[i + 1] -= 0.06 * dt;                       // buoyant dust barely sinks
            const drag = Math.exp(-1.6 * dt);
            P.vel[i] *= drag; P.vel[i + 1] *= drag; P.vel[i + 2] *= drag;
          }
          P.vel[i] += Math.sin(t * 1.3 + P.seed[k] * 40) * (chip ? 0.01 : 0.05) * dt;
          P.rot[k] += P.spin[k] * dt;
          P.hot[k] = P.heat[k] * Math.max(0, 1 - life * 1.8);
          const low = clamp01((P.pos[i + 1] + 0.72) / 0.25);
          alpha = Math.min(1, P.age[k] / 0.06) * Math.min(1, (1 - life) / 0.3) * low;
        }
        P.pos[i] += P.vel[i] * dt; P.pos[i + 1] += P.vel[i + 1] * dt; P.pos[i + 2] += P.vel[i + 2] * dt;
        const o = n * STRIDE;
        upload[o] = P.pos[i]; upload[o + 1] = P.pos[i + 1]; upload[o + 2] = P.pos[i + 2];
        upload[o + 3] = P.uv[k * 2]; upload[o + 4] = P.uv[k * 2 + 1];
        upload[o + 5] = alpha; upload[o + 6] = P.size[k]; upload[o + 7] = P.rot[k]; upload[o + 8] = kind;
        upload[o + 9] = P.hot[k]; upload[o + 10] = P.seed[k];
        n++;
      }
      alive = n;
    };

    // ---- interaction state ---------------------------------------------
    type Spring = { x: number; v: number; t: number };
    const sp = (x: number): Spring => ({ x, v: 0, t: x });
    const S = { rx: sp(0), ry: sp(0), lx: sp(-0.6), ly: sp(0.7), z: sp(0), scroll: sp(0) };
    const step = (s: Spring, k: number, d: number) => { s.v = (s.v + (s.t - s.x) * k) * d; s.x += s.v; };
    let pointer = { nx: 0, ny: 0 };
    let drag: null | { x: number; y: number; ox: number; oy: number; lastX: number; lastT: number; vel: number } = null;
    const turn = { x: 0, y: 0, vel: 0 };
    let hovering = false;
    let introStart = 0, last = 0, frontP = reduce ? 1.05 : -0.04;
    const soft = (v: number, lim: number) => lim * Math.tanh(v / lim);

    const retarget = () => {
      const scroll = S.scroll.t;
      S.ry.t = pointer.nx * 0.13 * amp + soft(turn.y, 0.24) + scroll * 0.1;
      S.rx.t = pointer.ny * 0.06 * amp + soft(turn.x, 0.07) - scroll * 0.04;
      S.lx.t = Math.max(-1.3, Math.min(1.3, pointer.nx * 1.5));
      S.ly.t = Math.max(-1, Math.min(1.3, -pointer.ny * 1.5 + 0.3));
      S.z.t = (hovering ? 0.05 : 0) - scroll * 0.15;
    };

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const w = box.clientWidth, h = box.clientHeight;
      if (!w || !h) return;
      cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);
      gl.viewport(0, 0, cv.width, cv.height);
      const proj = perspective(0.6, w / h, 0.1, 10);
      gl.useProgram(prog); gl.uniformMatrix4fv(u.proj, false, proj);
      gl.useProgram(pprog); gl.uniformMatrix4fv(pu.proj, false, proj); gl.uniform1f(pu.px, dpr);
      kick();
    };

    const onMove = (e: PointerEvent) => {
      const r = box.getBoundingClientRect();
      pointer = {
        nx: Math.max(-1, Math.min(1, ((e.clientX - (r.left + r.width / 2)) / window.innerWidth) * 2.2)),
        ny: Math.max(-1, Math.min(1, ((e.clientY - (r.top + r.height / 2)) / window.innerHeight) * 2.2)),
      };
      if (drag) {
        const now = performance.now();
        turn.y = drag.oy + (e.clientX - drag.x) * 0.003;
        turn.x = drag.ox + (e.clientY - drag.y) * 0.0015;
        drag.vel = (e.clientX - drag.lastX) / Math.max(now - drag.lastT, 1);
        drag.lastX = e.clientX; drag.lastT = now;
      }
      retarget(); kick();
    };
    const onDown = (e: PointerEvent) => {
      drag = { x: e.clientX, y: e.clientY, ox: turn.x, oy: turn.y, lastX: e.clientX, lastT: performance.now(), vel: 0 };
      cv.setPointerCapture(e.pointerId); box.classList.add("is-dragging");
    };
    const onUp = () => {
      if (!drag) return;
      turn.vel = drag.vel * 0.03;
      drag = null; box.classList.remove("is-dragging"); kick();
    };
    const onEnter = () => { hovering = true; retarget(); kick(); };
    const onLeave = () => { hovering = false; retarget(); kick(); };
    const onScroll = () => {
      const host = hostRef?.current; const h = host ? host.offsetHeight : window.innerHeight;
      S.scroll.t = clamp01(window.scrollY / h);
      retarget(); kick();
    };

    let running = false;
    const kick = () => { if (!running && visible && !disposed && cells) { running = true; last = 0; raf = requestAnimationFrame(frame); } };
    const host = hostRef?.current ?? null;

    function frame() {
      const now = performance.now();
      if (introStart === 0) introStart = now;
      const dt = last ? Math.min((now - last) / 1000, 0.05) : 1 / 60;
      last = now;
      const t = (now - introStart) / 1000;

      if (!drag) {
        turn.y += turn.vel; turn.vel *= 0.9;
        if (Math.abs(turn.vel) < 0.0005) { turn.y *= 0.92; turn.x *= 0.92; }
        retarget();
      }
      const K = drag ? 0.2 : 0.06, D = drag ? 0.66 : 0.84;
      step(S.rx, K, D); step(S.ry, K, D); step(S.z, 0.05, 0.85);
      step(S.lx, 0.05, 0.85); step(S.ly, 0.05, 0.85); step(S.scroll, 0.07, 0.82);

      // the front: rises through the statue on load, recedes top-down as you scroll away
      const introK = reduce ? 1 : easeInOut(clamp01((t - 0.15) / 3.2));
      const dissolve = smooth(0.1, 0.85, S.scroll.x);
      const target = -0.04 + 1.1 * introK * (1 - dissolve);
      const prev = frontP;
      frontP = target;
      if (!reduce) emitBetween(prev, frontP, frontP >= prev ? "form" : "fall");
      if (MAX) simulate(dt, t);

      const settle = reduce ? 1 : easeInOut(clamp01(t / 3.6));
      depthScale = 0.075 * (0.5 + 0.5 * settle);
      const lx = S.lx.x * settle + -1.4 * (1 - settle), ly = S.ly.x * settle + 1.2 * (1 - settle);

      const R = rot(S.rx.x, S.ry.x);
      const zBase = -1.9 + S.z.x;
      const model = mat4(R, 0, 0, zBase);
      gl!.clearColor(0, 0, 0, 0);
      gl!.clear(gl!.COLOR_BUFFER_BIT | gl!.DEPTH_BUFFER_BIT);

      gl!.useProgram(prog);
      gl!.bindVertexArray(meshVao);
      gl!.uniform1f(u.aspect, imgAspect);
      gl!.uniform3f(u.light, lx, ly, 0.8);
      gl!.uniformMatrix3fv(u.rot, false, new Float32Array(R));
      gl!.uniform1f(u.front, frontP);

      // shadow pass (flat, behind, pushed away from the light)
      gl!.disable(gl!.DEPTH_TEST);
      gl!.uniform1f(u.flat, 1);
      gl!.uniform1f(u.zoff, -0.14);
      gl!.uniform1f(u.shadowA, 0.55);
      gl!.uniformMatrix4fv(u.model, false, mat4(rot(S.rx.x * 0.6, S.ry.x * 0.6), -lx * 0.05, -ly * 0.04 - 0.015, zBase));
      gl!.drawElements(gl!.TRIANGLES, idx.length, gl!.UNSIGNED_INT, 0);

      // statue
      gl!.enable(gl!.DEPTH_TEST);
      gl!.depthMask(true);
      gl!.uniform1f(u.flat, 0);
      gl!.uniform1f(u.zoff, 0);
      gl!.uniform1f(u.depthScale, depthScale);
      gl!.uniformMatrix4fv(u.model, false, model);
      if (frontP > -0.03) gl!.drawElements(gl!.TRIANGLES, idx.length, gl!.UNSIGNED_INT, 0);

      // dust
      if (alive > 0) {
        gl!.useProgram(pprog);
        gl!.bindVertexArray(pVao);
        gl!.bindBuffer(gl!.ARRAY_BUFFER, pBuf);
        gl!.bufferSubData(gl!.ARRAY_BUFFER, 0, upload, 0, alive * STRIDE);
        gl!.uniformMatrix4fv(pu.model, false, model);
        gl!.uniform3f(pu.light, lx, ly, 0.8);
        gl!.uniform1f(pu.aspect, imgAspect);
        gl!.depthMask(false);
        gl!.drawArrays(gl!.POINTS, 0, alive);
        gl!.depthMask(true);
      }
      gl!.bindVertexArray(null);

      if (host) {
        host.style.setProperty("--rx", S.rx.x.toFixed(4));
        host.style.setProperty("--ry", S.ry.x.toFixed(4));
        host.style.setProperty("--lx", lx.toFixed(4));
        host.style.setProperty("--ly", ly.toFixed(4));
      }
      const springs = Object.values(S);
      const moving = (!reduce && t < 3.7) || alive > 0 || Math.abs(turn.vel) > 0.0005 || Math.abs(turn.y) > 0.001 ||
        springs.some((s) => Math.abs(s.v) > 1e-5 || Math.abs(s.t - s.x) > 1e-4);
      if (moving && visible && !disposed) raf = requestAnimationFrame(frame); else running = false;
    }

    Promise.all([load(src), load(depthSrc), load(normalSrc)]).then(([img, dep, nrm]) => {
      if (disposed) return;
      imgAspect = img.naturalWidth / img.naturalHeight;
      texture(img, 0, true);
      texture(dep, 1, false, false);   // NEAREST: packed 16-bit depth must not be interpolated
      texture(nrm, 2, false);

      // shared reveal field
      const FW = 256, FH = Math.round(FW / imgAspect);
      front = buildFront(FW, FH);
      const bytes = new Uint8Array(FW * FH);
      for (let i = 0; i < bytes.length; i++) bytes[i] = Math.round(front[i] * 255);
      gl.activeTexture(gl.TEXTURE3);
      gl.bindTexture(gl.TEXTURE_2D, gl.createTexture());
      gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.R8, FW, FH, 0, gl.RED, gl.UNSIGNED_BYTE, bytes);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);

      // solid surface cells (alpha + depth), sorted by when the front reaches them
      const sample = (im: HTMLImageElement) => {
        const c = document.createElement("canvas"); c.width = GW; c.height = GH;
        const x = c.getContext("2d", { willReadFrequently: true })!;
        x.imageSmoothingEnabled = false;   // packed depth bytes must not be averaged
        x.drawImage(im, 0, 0, GW, GH);
        return x.getImageData(0, 0, GW, GH).data;
      };
      const colPx = sample(img), depPx = sample(dep);
      const list: number[] = [];
      for (let y = 0; y < GH; y++) for (let x = 0; x < GW; x++) if (colPx[(y * GW + x) * 4 + 3] > 150) list.push(y * GW + x);
      const fAt = (ux: number, uy: number) => front![Math.min(FH - 1, Math.floor(uy * FH)) * FW + Math.min(FW - 1, Math.floor(ux * FW))];
      const tmp = list.map((c) => {
        const x = c % GW, y = (c / GW) | 0, ux = (x + 0.5) / GW, uy = (y + 0.5) / GH;
        const o = c * 4, d = (depPx[o] * 256 + depPx[o + 2]) / 65535;
        return { ux, uy, d, t: fAt(ux, uy) };
      }).sort((a, b) => a.t - b.t);
      cells = { u: new Float32Array(tmp.map((c) => c.ux)), v: new Float32Array(tmp.map((c) => c.uy)), d: new Float32Array(tmp.map((c) => c.d)), t: new Float32Array(tmp.map((c) => c.t)), n: tmp.length };

      gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
      resize(); onScroll();
      setReady(true);
      kick();
    }).catch((e) => { console.warn(e); setFallback(true); });

    const ro = new ResizeObserver(resize); ro.observe(box);
    const io = new IntersectionObserver(([en]) => { visible = en.isIntersecting; if (visible) kick(); });
    io.observe(box);
    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("scroll", onScroll, { passive: true });
    cv.addEventListener("pointerdown", onDown);
    cv.addEventListener("pointerenter", onEnter);
    cv.addEventListener("pointerleave", onLeave);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    return () => {
      disposed = true; cancelAnimationFrame(raf); ro.disconnect(); io.disconnect();
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("scroll", onScroll);
      cv.removeEventListener("pointerdown", onDown);
      cv.removeEventListener("pointerenter", onEnter);
      cv.removeEventListener("pointerleave", onLeave);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
  }, [src, depthSrc, normalSrc, hostRef]);

  return (
    <div ref={wrap} className={`statue ${ready ? "is-ready" : ""} ${fallback ? "is-fallback" : ""}`}>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src={src} alt={fallback ? alt : ""} aria-hidden={!fallback} className="statue-poster" />
      {!fallback && <canvas ref={canvas} role="img" aria-label={alt} />}
    </div>
  );
}
